FIELDS = (
    "name", "name_ar", "name_fr", "overview", "overview_ar", "overview_fr", "years_experience",
    "completed_projects", "ongoing_projects", "rating", "location", "location_ar", "location_fr",
    "email", "phone", "website", "related_projects",
)


def seed_profiles(apps, schema_editor):
    """Save every developer already entered on a property as a profile (first one per name) and
    link the property to it, so the list starts with the platform's real developers."""
    DeveloperInfo = apps.get_model("properties", "DeveloperInfo")
    DeveloperProfile = apps.get_model("properties", "DeveloperProfile")
    for info in DeveloperInfo.objects.order_by("id"):
        name = (info.name or "").strip()
        if not name:
            continue
        profile = DeveloperProfile.objects.filter(name=name).first()
        if profile is None:
            profile = DeveloperProfile.objects.create(**{f: getattr(info, f) for f in FIELDS if f != "name"}, name=name)
        info.profile_id = profile.pk
        info.save(update_fields=["profile"])


